CREATE OR REPLACE FUNCTION public.client_gym_directory() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',g.id,'gyvoraId',g.gyvora_id,'name',g.name,'location',coalesce(r.data->>'location',''),'image',coalesce(r.data->>'cover',''),'description',coalesce(r.data->>'description',''))),'[]'::jsonb) FROM public.gyms g LEFT JOIN public.gym_records r ON r.gym_id=g.id AND r.kind='gym' WHERE public.gym_operational(g.id) $$;